INSERT INTO `instructors` VALUES (1,'Ирина Соколова','Классический и лечебный массаж','Обучаю классическому массажу с 2014 года. Работала с профессиональными спортсменами и клиентами с хроническими болями в спине. Автор методики «мягкого глубокого прорабатывания».','12 лет практики, сертификаты FISIOTERAPIA','','{\"telegram\":\"irina_massage\",\"instagram\":\"irina.sokolova\",\"vk\":\"irina_sokolova\",\"email\":\"irina@courses.ru\"}','2026-08-11 12:46:36'),(2,'Сергей Морозов','Лечебный массаж и реабилитация','Врач-реабилитолог и массажист. Специализируюсь на лечебном массаже позвоночника и реабилитации после травм. Преподаю диагностику осанки и работу с триггерными точками.','15 лет практики, мед. образование','','{\"telegram\":\"sergey_morozov\",\"youtube\":\"morozovrehab\",\"phone\":\"+79990001122\"}','2026-08-11 12:46:36'),(3,'Алексей Волков','Спортивный массаж','Мастер спорта по дзюдо, сертифицированный спортивный массажист. Работал с командами по футболу и боксу. Обучаю разминочному, восстановительному массажу и работе при травмах.','10 лет практики, МС по дзюдо','','{\"instagram\":\"volkov.sport\",\"vk\":\"alex_volkov\",\"whatsapp\":\"79991112233\"}','2026-08-11 12:46:36'),(4,'Ким Сурайя','Тайский традиционный массаж','Потомственный тайский массажист. Обучалась в школе Wat Pho (Бангкок) и в Чиангмае. Передаёт традиционные техники давления, энергетические линии и стрейчинг.','20 лет практики, обучение в Чиангмае','','{\"instagram\":\"kim.suraya\",\"youtube\":\"kimthai\"}','2026-08-11 12:46:36'),(5,'Елена Кузнецова','Детский массаж','Педиатрический массажист. Научила массажу и гимнастике сотни родителей. Курс построен на безопасных игровых техниках для детей от рождения до 3 лет.','9 лет практики, курс по детскому массажу','','{\"telegram\":\"elena_kids\",\"email\":\"elena@courses.ru\"}','2026-08-11 12:46:36'),(7,'Анна Матвеева','Массажист-терапевт, стаж 12 лет','Ведущий специалист по классическому, лечебному и лимфодренажному массажу. Проводит обучение мастеров, ведёт приём и контролирует качество сеансов.','12 лет','/uploads/svetlana.svg',NULL,'2026-08-14 21:18:19');
