INSERT INTO `lessons` VALUES (1,1,'Введение в классический массаж','Классический (шведский) массаж — фундамент всей мануальной терапии. Это система приёмов, которые воздействуют на кожу, мышцы и кровообращение: поглаживание, выжимание, растирание, разминание, вибрация и ударные приёмы.\n\nИстория метода насчитывает более ста лет: современную систему систематизировал в XIX веке шведский врач Пер Генрик Линг. Сегодня классический массаж применяют и в оздоровительных, и в лечебных целях.\n\nЭффекты сеанса: улучшение крово- и лимфотока, снятие мышечного гипертонуса, ускорение обменных процессов, нормализация тонуса нервной системы. Регулярный курс помогает бороться с усталостью, отёками и стрессом.\n\nПоказания: мышечное перенапряжение, малоподвижный образ жизни, восстановление после нагрузок, профилактика остеохондроза.\n\nПротивопоказания: острые воспаления, высокая температура, заболевания крови, варикоз в стадии обострения, злокачественные новообразования, первые месяцы беременности. При сомнениях всегда уточняйте состояние клиента.',20,0,'https://www.youtube.com/watch?v=WEajwQ57V0Q','/uploads/lesson-hands.svg','[{\"q\":\"Кто систематизировал классический (шведский) массаж в XIX веке?\",\"options\":[\"Жан-Мартен Шарко\",\"Пер Генрик Линг\",\"Хиппократ\",\"Дживака Кумарбхаши\"],\"correct\":1}]'),(2,1,'Анатомия и организация рабочего места','Чтобы массаж был безопасным и эффективным, нужно понимать, где проходят крупные мышцы, связки и нервные пучки.\n\nКлючевые зоны спины: трапециевидная мышца (верхняя часть — частая причина боли в шее), широчайшая мышца спины, мышца, выпрямляющая позвоночник, и ромбовидные мышцы между лопатками.\n\nРабочее место: кушетка высотой на уровне вашего кулака, плотное полотенце, гипоаллергенное массажное масло или крем. Температура в кабинете — комфортная (22–24 °C), освещение мягкое, без прямого света в глаза клиенту.\n\nПравильная стойка мастера: ноги на ширине плеч, корпус ровный, работайте за счёт веса тела, а не силы рук. Это позволит работать без усталости даже с глубокими техниками.\n\nПеред сеансом спросите клиента о самочувствии, давлении и противопоказаниях. Соберите короткий анамнез — это профессиональная норма.',35,1,'https://www.youtube.com/watch?v=Y1P_jUfI6AY','/uploads/lesson-anatomy.svg','[{\"q\":\"На какой высоте должна быть кушетка для мастера?\",\"options\":[\"На уровне пояса мастера\",\"На уровне кулака мастера\",\"Как можно выше\",\"Ниже колен\"],\"correct\":1}]'),(3,1,'Базовые приёмы: поглаживание и растирание','Сеанс всегда начинается и заканчивается поглаживанием (эффлеражем) — поверхностным и глубоким. Оно разогревает ткани, успокаивает нервную систему и готовит мышцы к более глубоким приёмам.\n\nТехника: ладони скользят вдоль мышечных волокон от поясницы к лопаткам и плечам. Давление нарастает постепенно, движения медленные и ритмичные.\n\nВторой базовый приём — растирание. Это смещение и растяжение кожи и подкожных тканей. Выполняется подушечками пальцев, ребром ладони или основанием ладони. Растирание улучшает кровоток в месте воздействия и «прогревает» глубокие слои.\n\nТипичная ошибка новичков — слишком быстрое и поверхностное растирание. Темп должен быть неторопливым, а амплитуда — достаточной, чтобы смещать ткани, а не «гладить» кожу.',50,2,'https://www.youtube.com/watch?v=wRr_vgUojZg','/uploads/lesson-oil.svg','[{\"q\":\"С чего всегда начинается классический сеанс?\",\"options\":[\"С разминания\",\"С поглаживания\",\"С вибрации\",\"С поколачивания\"],\"correct\":1},{\"q\":\"Какова главная задача растирания?\",\"options\":[\"Расслабить психику\",\"Прогреть ткани и усилить кровоток\",\"Убрать жир\",\"Размять суставы\"],\"correct\":1}]'),(4,1,'Глубокие приёмы: разминание и вибрация','Разминание — основной приём глубокого воздействия. Мышца захватывается, приподнимается, отжимается и «перекатывается» между ладонью и пальцами.\n\nВыполняйте разминание медленно и глубоко, двигаясь от центра спины к периферии. В зоне между лопатками работайте основанием ладони — трапеция часто бывает плотной и болезненной.\n\nВибрация — это ритмичное сотрясение тканей с частотой до нескольких сотен колебаний в минуту. Она снимает тонус, улучшает капиллярное кровообращение. Продолжительность вибрации на одной зоне — не более 10–15 секунд.\n\nПоколачивание и рубление применяются в конце сеанса как тонизирующие приёмы. Не выполняйте их на пояснице, шее и в области почек.\n\nГлавное правило глубокой работы: «без боли». Ориентируйтесь на ощущения клиента — рабочая интенсивность находится на границе лёгкого дискомфорта, но не острой боли.',65,3,'https://www.youtube.com/watch?v=xAonJYoJFZg','/uploads/lesson-pressure.svg','[{\"q\":\"Какой приём считается основным для глубокой проработки мышц?\",\"options\":[\"Поглаживание\",\"Разминание\",\"Растирание\",\"Поколачивание\"],\"correct\":1},{\"q\":\"На каких зонах нельзя выполнять ударные приёмы?\",\"options\":[\"На плечах\",\"На пояснице и в области почек\",\"На бёдрах\",\"На икрах\"],\"correct\":1}]'),(5,1,'Построение полноценного сеанса','Грамотный сеанс длится 50–60 минут и строится по принципу «от поверхностного к глубокому и снова к поверхностному».\n\nСхема: поглаживание (5 мин) → растирание и разогрев (10 мин) → разминание глубоких зон (25–30 мин) → вибрация и ударные приёмы (5 мин) → расслабляющее поглаживание (5 мин).\n\nПорядок проработки: сначала спина и шея, затем ноги, руки, живот и грудь (если нет противопоказаний).\n\nПосле сеанса дайте клиенту полежать 3–5 минут и выпить стакан воды — это помогает вывести продукты метаболизма.\n\nВ этом уроке вы выполняете итоговый проект: собираете полный сеанс классического массажа, фиксируете последовательность и время приёмов, затем сдаёте описание преподавателю.',80,4,'https://www.youtube.com/watch?v=WEajwQ57V0Q','/uploads/lesson-cert.svg','[{\"q\":\"Сколько длится грамотный классический сеанс?\",\"options\":[\"15–20 минут\",\"30 минут\",\"50–60 минут\",\"2 часа\"],\"correct\":2}]'),(6,2,'Боль в спине: причины и диагностика','Боль в спине — самая частая жалоба в практике массажиста. По статистике, 80% людей хотя бы раз в жизни испытывают боль в пояснице, а с шеей проблемы есть у каждого третьего.\n\nОсновные причины: длительное сидение, мышечный дисбаланс, слабый мышечный корсет, стресс и привычные «защитные» позы.\n\nПеред работой важно провести простую диагностику: визуальную оценку осанки (асимметрия плеч, лопаток, таза), пальпацию на предмет триггерных точек и зон напряжения, вопросы о характере боли.\n\nКрасные флаги, при которых массаж не проводится и нужен врач: острая боль при движениях, онемение конечностей, боль после травмы, повышение температуры, слабость в ногах.\n\nЗапомните: массажист снимает мышечное напряжение, но не лечит межпозвоночные грыжи и воспаления. Работайте в связке с врачом.',20,0,'https://www.youtube.com/watch?v=xAonJYoJFZg','/uploads/lesson-neck.svg','[{\"q\":\"Какой процент людей хотя бы раз в жизни испытывает боль в пояснице?\",\"options\":[\"Около 30%\",\"Около 50%\",\"Около 80%\",\"100%\"],\"correct\":2}]'),(7,2,'Анатомия позвоночника и постуральные мышцы','Позвоночник состоит из 33–34 позвонков: 7 шейных, 12 грудных, 5 поясничных, крестца и копчика. Между позвонками — межпозвоночные диски, выполняющие роль амортизаторов.\n\nПри сидячей работе страдают прежде всего глубокие мышцы-стабилизаторы: многораздельные мышцы, поперечно-остистые и подвздошно-рёберные.\n\nТрапециевидная и ромбовидные мышцы отвечают за положение лопаток. При их перенапряжении появляется характерная «зажатость» между лопатками и боль в шее.\n\nКвадратная мышца поясницы при гипертонусе укорачивает поясницу и создаёт ложную асимметрию таза.\n\nНа этом уроке вы научитесь находить эти мышцы пальпаторно и понимать, какая зона даёт конкретную боль.',35,1,'https://www.youtube.com/watch?v=RPDJyreHqlE','/uploads/lesson-anatomy.svg','[{\"q\":\"Сколько позвонков входит в позвоночник человека?\",\"options\":[\"24\",\"33–34\",\"40\",\"12\"],\"correct\":1}]'),(8,2,'Триггерные точки шейно-воротниковой зоны','Триггерная точка — это уплотнённый участок мышечного волокна, который отдаёт боль в другие зоны (так называемая отражённая боль).\n\nЧастые триггеры шеи: верхняя порция трапеции (боль в виске и шее), грудино-ключично-сосцевидная мышца (головные боли, головокружение), лестничные мышцы (онемение пальцев).\n\nТехника работы: найдите тугой тяж пальцами, зафиксируйте его и выполняйте медленное изометрическое давление 30–60 секунд до появления «теплоты» и расслабления. Затем растяните мышцу.\n\nРабота с триггерными точками — медленная и терпеливая. Давление должно быть достаточным, но не вызывать резкой боли.',50,2,'https://www.youtube.com/watch?v=-iOW54YJ1Xs','/uploads/lesson-pressure.svg','[{\"q\":\"Что такое триггерная точка?\",\"options\":[\"Воспаление нерва\",\"Уплотнённый участок мышцы, дающий отражённую боль\",\"Гематома\",\"Спазм сосудов\"],\"correct\":1},{\"q\":\"Сколько длится давление на триггерную точку?\",\"options\":[\"2–3 секунды\",\"10–15 секунд\",\"30–60 секунд\",\"Несколько минут\"],\"correct\":2}]'),(9,2,'Глубокие техники для спины','Для глубокой проработки спины используйте комбинацию приёмов: разминание основанием ладони вдоль паравертебральных мышц, локтевое давление по волокнам, растяжение трапеции.\n\nПозиция клиента — лежа на животе с валиком под грудью. Начинайте с поясницы, постепенно поднимаясь к шее.\n\nПри работе с лопатками попросите клиента завести руку за спину — так раскрывается подлопаточная зона.\n\nГлубокие техники выполняются на выдохе клиента. Дыхание — ваш главный помощник: на выдохе мышечный тонус снижается, и давление воспринимается легче.\n\nПосле глубокой работы обязательно завершите зону поглаживанием, чтобы снять перевозбуждение тканей.',65,3,'https://www.youtube.com/watch?v=KI5lZg_R9Gs','/uploads/lesson-neck.svg','[{\"q\":\"В каком положении клиента удобнее работать с глубокими мышцами спины?\",\"options\":[\"Лёжа на животе с валиком\",\"Сидя\",\"Стоя\",\"Лёжа на боку\"],\"correct\":0},{\"q\":\"Когда лучше выполнять глубокое давление?\",\"options\":[\"На вдохе клиента\",\"На выдохе клиента\",\"В момент задержки дыхания\",\"Не важно\"],\"correct\":1}]'),(10,2,'Программа лечения и профилактика','Лечебный массаж работает курсами. Оптимальная схема: 8–12 сеансов 2–3 раза в неделю, затем поддерживающий курс раз в месяц.\n\nТиповая программа при болях в шее: мягкая работа с трапецией и лестничными мышцами, триггерные точки, тракция шейного отдела, постизометрическое расслабление.\n\nВажная часть — рекомендации клиенту: перерывы в работе за компьютером каждые 45–60 минут, разминка для шеи, правильная подушка, укрепление мышечного корсета.\n\nИтоговый проект: составьте программу из 8 сеансов для клиента с болью в шее, опишите цели каждого этапа и подберите домашние упражнения.',80,4,'https://www.youtube.com/watch?v=rWXvhPkLmLc','/uploads/lesson-cert.svg','[{\"q\":\"Какая схема лечебного массажа при болях в шее считается оптимальной?\",\"options\":[\"1 сеанс\",\"8–12 сеансов 2–3 раза в неделю\",\"20 сеансов ежедневно\",\"2 сеанса в год\"],\"correct\":1}]'),(11,3,'Роль массажа в подготовке спортсмена','Спортивный массаж — это система, направленная на подготовку организма к нагрузкам, восстановление и профилактику травм.\n\nВ отличие от классического, спортивный массаж решает конкретные задачи: улучшить кровоснабжение мышц перед стартом, снять усталость после тренировки, уменьшить крепатуру, восстановить подвижность после травм.\n\nВиды спортивного массажа: предварительный (разминочный и предстартовый), восстановительный, тренировочный, реабилитационный и гигиенический.\n\nСпортивный массаж выполняется быстрее и энергичнее классического: темп движений выше, а между приёмами почти нет пауз.',20,0,'https://www.youtube.com/watch?v=OB2FJaYrFFY','/uploads/lesson-sport.svg','[{\"q\":\"Что из перечисленного НЕ является видом спортивного массажа?\",\"options\":[\"Разминочный\",\"Восстановительный\",\"Реабилитационный\",\"Лимфодренажный\"],\"correct\":3}]'),(12,3,'Разминочный массаж перед нагрузкой','Разминочный массаж проводится за 10–15 минут до тренировки или старта. Его цель — разогреть мышцы, повысить их эластичность и настроить на работу.\n\nТехника: энергичное поглаживание и растирание 5–7 минут, затем быстрые разминания основных мышечных групп, лёгкие вибрации и поколачивание.\n\nПредстартовый массаж может быть тонизирующим (если спортсмен вялый) или успокаивающим (если излишне возбуждён).\n\nНе выполняйте глубокую работу перед нагрузкой — это снизит силу и скорость. Движения короткие, быстрые, направленные на разогрев.',35,1,'https://www.youtube.com/watch?v=w8kEQoyEmAs','/uploads/lesson-sport.svg','[{\"q\":\"За сколько минут до нагрузки проводится разминочный массаж?\",\"options\":[\"За 30–60 минут\",\"За 10–15 минут\",\"За 2 часа\",\"Прямо во время старта\"],\"correct\":1}]'),(13,3,'Восстановительный массаж после тренировки','Восстановительный массаж проводится через 1–2 часа после нагрузки или на следующий день. Задача — ускорить выведение продуктов метаболизма и снять мышечное утомление.\n\nНачните с общих поглаживаний для оценки состояния мышц, затем проработайте самые «забитые» группы: квадрицепсы, ягодицы, икры, мышцы спины.\n\nИспользуйте разминание, растирание и вибрации средней интенсивности. Продолжительность — 20–40 минут.\n\nПосле сеанса спортсмену рекомендованы тёплый душ, вода и полноценный сон.',50,2,'https://www.youtube.com/watch?v=HjwWKsvRD-M','/uploads/lesson-stretch.svg','[{\"q\":\"Через какое время после нагрузки проводят восстановительный массаж?\",\"options\":[\"Сразу после тренировки\",\"Через 1–2 часа или на следующий день\",\"Через неделю\",\"Перед следующей тренировкой\"],\"correct\":1},{\"q\":\"Какова основная задача восстановительного массажа?\",\"options\":[\"Разогреть мышцы\",\"Снять утомление и ускорить восстановление\",\"Увеличить силу\",\"Растянуть связки\"],\"correct\":1}]'),(14,3,'Крепатура, травмы и реабилитация','Крепатура — мышечная боль после непривычной нагрузки. В первые 24–72 часа она считается нормой; задача массажиста — ускорить восстановление и уменьшить болезненность.\n\nРабота с крепатурой: мягкое поглаживание, лёгкое растирание, центростремительные движения по ходу венозного оттока. Избегайте грубого глубокого разминания на пике боли.\n\nПри травмах (растяжения, ушибы) массаж проводят только после консультации врача и в подостром периоде. Работать можно с соседними зонами и рубцами, но не на самом месте повреждения.\n\nРеабилитационный массаж сочетают с пассивной и активной гимнастикой для восстановления подвижности суставов.',65,3,'https://www.youtube.com/watch?v=p1igSbjKG5M','/uploads/lesson-sport.svg','[{\"q\":\"Что такое крепатура?\",\"options\":[\"Воспаление сустава\",\"Мышечная боль после непривычной нагрузки\",\"Перелом\",\"Судорога\"],\"correct\":1},{\"q\":\"Как работают с мышцей на пике крепатуры?\",\"options\":[\"Глубоко и грубо\",\"Мягко, лёгкими приёмами\",\"Ударными техниками\",\"Вообще не трогают\"],\"correct\":1}]'),(15,3,'Миофасциальный релиз и итоговый сеанс','Миофасциальный релиз (МФР) — работа с фасциями, соединительнотканными оболочками мышц. Зажатая фасция ограничивает движение и ухудшает кровоснабжение.\n\nТехника: медленное давление и «раскатывание» ткани, пока она не «поплывёт» и не расслабится. Используйте локти, предплечья и кулак мастера, а также массажные роллы.\n\nМФР отлично сочетается со спортивным массажем: начните сеанс с релиза фасций, затем переходите к разминанию мышц.\n\nИтоговый проект: разработайте программу восстановления на 7 дней после соревнований, включив восстановительный массаж, МФР и растяжку.',80,4,'https://www.youtube.com/watch?v=WYKjrShbmbQ','/uploads/lesson-cert.svg','[{\"q\":\"Что такое фасция?\",\"options\":[\"Крупная вена\",\"Соединительнотканная оболочка мышцы\",\"Костный нарост\",\"Нервный узел\"],\"correct\":1}]'),(16,4,'Философия, сен-линии и принципы тайского массажа','Тайский массаж — древняя практика, которой более 2500 лет. По преданию, её создал врач Дживака Кумарбхаши, современник Будды.\n\nВ основе метода — учение о сен-линиях: энергетических каналах, по которым движется жизненная энергия. Тайский массаж работает с 10 основными сен-линиями.\n\nПринципы: давление, ритмичное покачивание, стрейчинг и «йога для пассивного тела». Мастер ведёт тело клиента, словно в танце.\n\nМассаж выполняется на мате на полу, клиент — в удобной свободной одежде. Это делает тайский массаж уникальным среди других техник.',20,0,'https://www.youtube.com/watch?v=V24Y-2Ii0cM','/uploads/lesson-thai.svg','[{\"q\":\"Кому по преданию приписывают создание тайского массажа?\",\"options\":[\"Будде\",\"Дживаке Кумарбхаши\",\"Перу Генрику Лингу\",\"Гиппократу\"],\"correct\":1}]'),(17,4,'Подготовка и техника давления','Перед сеансом разогрейте клиента лёгкими покачиваниями и растираниями стоп. Тайский массаж всегда начинается со стоп — там начинаются сен-линии.\n\nБазовые инструменты давления: большой палец, ладонь, основание ладони, локоть, колено и стопа.\n\nПравило большого пальца: давление выполняется всей подушечкой пальца, перпендикулярно поверхности тела, с постепенным нарастанием и медленным снятием.\n\nПеред переходом к глубокому давлению всегда «спрашивайте» ткани: выполните пробное давление и оцените реакцию клиента.',35,1,'https://www.youtube.com/watch?v=D-mzFt0mC2M','/uploads/lesson-thai.svg','[{\"q\":\"С какой части тела всегда начинается тайский массаж?\",\"options\":[\"Со спины\",\"С головы\",\"Со стоп\",\"С рук\"],\"correct\":2}]'),(18,4,'Давление ладонью, большим пальцем и стопой','Давление ладонью — универсальный приём для ног, спины и рук. Ладонь мягко «вливается» в ткани, передавая вес тела.\n\nДавление большим пальцем — точечная работа вдоль сен-линий на стопах, голенях и ладонях. Это кропотливая техника, требующая хорошей подготовки пальцев.\n\nДавление стопой используется на бёдрах, ягодицах и спине. Мастер держится за балки или опору и контролирует силу через собственный вес.\n\nОсваивайте каждое давление по отдельности, на мягкой поверхности, следя за устойчивостью собственного корпуса.',50,2,'https://www.youtube.com/watch?v=7zRbKuLPs9M','/uploads/lesson-pressure.svg','[{\"q\":\"Каким инструментом выполняется точечное давление вдоль сен-линий?\",\"options\":[\"Кулаком\",\"Большим пальцем\",\"Локтем\",\"Коленом\"],\"correct\":1},{\"q\":\"С какой части тела начинается классический тайский массаж?\",\"options\":[\"Со спины\",\"Со стоп\",\"С головы\",\"С рук\"],\"correct\":1}]'),(19,4,'Стрейчинг: работа с ногами и тазом','Стрейчинг — «визитная карточка» тайского массажа. Благодаря ему техника называется «пассивной йогой».\n\nБазовые растяжки: подъём ноги с упором стопы в плечо, скручивание корпуса с фиксацией бедра, «крокодил» — скручивание в положении лёжа.\n\nПравила безопасности: растягивайте постепенно, до лёгкого натяжения, никогда не до боли. Всегда поддерживайте конечность и контролируйте амплитуду.\n\nРитм: вдох — клиент расслабляется, выдох — углубляете растяжку. Покачивания чередуются с удержанием позиции 3–5 секунд.',65,3,'https://www.youtube.com/watch?v=8WJITqiFmm4','/uploads/lesson-stretch.svg','[{\"q\":\"Какой ритм используется при тайском стрейчинге?\",\"options\":[\"Растяжка на вдохе клиента\",\"Растяжка на выдохе клиента\",\"Без связи с дыханием\",\"Быстрые рывки\"],\"correct\":1},{\"q\":\"До какого предела выполняется растяжка?\",\"options\":[\"До острой боли\",\"До лёгкого натяжения без боли\",\"До хруста в суставах\",\"До максимального усилия\"],\"correct\":1}]'),(20,4,'Полная последовательность сеанса','Традиционный сеанс длится 90 минут и делится на этапы: подготовка и работа со стопами → ноги и таз → спина → руки и шея → заключительный отдых.\n\nНа каждом этапе чередуются давления и стрейчинг: это поддерживает интерес тела и усиливает эффект.\n\nЗавершается сеанс лёгким покачиванием всего тела и рекомендацией полежать 5 минут и выпить тёплой воды.\n\nИтоговый проект: соберите и опишите собственную последовательность тайского сеанса на 60 минут с указанием приёмов и их порядка.',80,4,'https://www.youtube.com/watch?v=X-pranOZDs0','/uploads/lesson-cert.svg','[{\"q\":\"Сколько длится традиционный тайский сеанс?\",\"options\":[\"30 минут\",\"60 минут\",\"90 минут\",\"3 часа\"],\"correct\":2}]'),(21,5,'Зачем малышам массаж','Детский массаж — один из самых полезных подарков, который родитель может дать малышу. Он укрепляет связь между взрослым и ребёнком, успокаивает и помогает развитию.\n\nПольза: улучшение пищеварения и снятие колик, более спокойный сон, укрепление мышц и иммунитета, стимуляция нервной системы, развитие тактильного восприятия.\n\nМалыши, которые получают регулярный массаж, реже плачут и быстрее набирают вес.\n\nВажно: массаж — это игра и общение. Следите за настроением ребёнка и прекращайте сеанс, если он капризничает.',20,0,'https://www.youtube.com/watch?v=uOx14qaAglE','/uploads/lesson-baby.svg','[{\"q\":\"Какой эффект даёт регулярный детский массаж?\",\"options\":[\"Ухудшение сна\",\"Крепче связь с родителем и спокойный сон\",\"Замедление развития\",\"Снижение иммунитета\"],\"correct\":1}]'),(22,5,'Безопасность и подготовка','Массаж проводится не раньше чем через 40–60 минут после еды. Ребёнок должен быть сытым, но не переполненным, и в хорошем настроении.\n\nПомещение: тёплая комната (24–26 °C), мягкая поверхность, крем или масло с нейтральным запахом без эфирных масел.\n\nРуки взрослого: чистые, тёплые, без украшений, короткие ногти. Снимите кольца и браслеты.\n\nЗапрещено массировать: при повышенной температуре, сыпи, кожных заболеваниях, а также область пупочной ранки до её заживления и зону родничка.\n\nДвижения — мягкие, поглаживающие, с улыбкой и спокойным голосом.',35,1,'https://www.youtube.com/watch?v=spd3VbDU25w','/uploads/lesson-baby.svg','[{\"q\":\"Через какое время после еды можно делать массаж малышу?\",\"options\":[\"Сразу\",\"Через 5 минут\",\"Через 40–60 минут\",\"Только на голодный желудок\"],\"correct\":2}]'),(23,5,'Массаж животика при коликах','Колики беспокоят большинство малышей в первые месяцы жизни. Деликатный массаж живота — один из самых безопасных способов облегчить состояние.\n\nТехника «солнышко»: тёплой ладонью выполняйте круговые движения по часовой стрелке вокруг пупка. Это совпадает с ходом толстой кишки и помогает отхождению газов.\n\nДополнительно: сгибание ножек к животику («велосипед»), прижимание коленей к животу на выдохе малыша.\n\nМассируйте 3–5 минут после тёплой ванны или между кормлениями. Движения — плавные, без нажима.\n\nЕсли ребёнок кричит, синеет или не успокаивается — немедленно прекратите и обратитесь к врачу.',50,2,'https://www.youtube.com/watch?v=spd3VbDU25w','/uploads/lesson-baby.svg','[{\"q\":\"В каком направлении массируют животик при коликах?\",\"options\":[\"Против часовой стрелки\",\"По часовой стрелке\",\"В любом\",\"Снизу вверх\"],\"correct\":1},{\"q\":\"Когда можно массировать животик малыша?\",\"options\":[\"Сразу после плотного кормления\",\"Между кормлениями, через 40–60 минут\",\"Когда малыш плачет от голода\",\"Перед сном всегда\"],\"correct\":1}]'),(24,5,'Гимнастика и игровые техники','Детский массаж прекрасно сочетается с лёгкой гимнастикой: движения становятся игрой и помогают малышу освоить своё тело.\n\nИгровые техники: «сорока-ворона» (поглаживание ладошек), «велосипед» (сгибание ножек), разведение рук с нежным поглаживанием, «лягушка» для тазобедренных суставов.\n\nЧередуйте поглаживание каждой части тела с весёлыми комментариями — ребёнок воспринимает сеанс как игру.\n\nПродолжительность для новорождённого — 5–7 минут, к году — 15–20 минут. Следите за реакцией и уважайте границы малыша.',65,3,'https://www.youtube.com/watch?v=uOx14qaAglE','/uploads/lesson-stretch.svg','[{\"q\":\"Сколько длится массаж для новорождённого?\",\"options\":[\"5–7 минут\",\"30 минут\",\"1 час\",\"Не важно\"],\"correct\":0},{\"q\":\"Что делать, если малышу не нравится массаж?\",\"options\":[\"Продолжать, закаляя характер\",\"Прекратить и попробовать позже\",\"Делать быстрее\",\"Добавить масла\"],\"correct\":1}]'),(25,5,'Ритуал перед сном и режим','Массаж перед сном превращается в приятный ритуал: тёплая ванна → нежный массаж → кормление → сон. Такая последовательность помогает малышу быстрее успокаиваться.\n\nДля вечернего сеанса используйте плавные поглаживания без тонизирующих приёмов, говорите тихим голосом, приглушите свет.\n\nРегулярность важнее длительности: 10 минут каждый день приносят больше пользы, чем час раз в неделю.\n\nИтоговый проект: составьте недельный план массажа для ребёнка 3–6 месяцев с указанием техник по дням и режимом.',80,4,'https://www.youtube.com/watch?v=spd3VbDU25w','/uploads/lesson-cert.svg','[{\"q\":\"Что рекомендовано делать непосредственно перед вечерним массажем?\",\"options\":[\"Активные игры\",\"Тёплую ванну\",\"Громкую музыку\",\"Плотный ужин\"],\"correct\":1}]');
/*!40000 ALTER TABLE `lessons` ENABLE KEYS */;
UNLOCK TABLES;

