INSERT INTO `services` VALUES (1,'Классический массаж','Полный сеанс классического массажа: разогрев, глубокая проработка мышц, расслабление.',2000.00,60,'💆','2026-08-14 20:56:24',7,'/uploads/course-classic.svg'),(2,'Массаж спины и шеи','Лечебный массаж шейно-воротниковой зоны: снятие спазма, работа с триггерными точками.',1500.00,45,'🦴','2026-08-14 20:56:24',7,'/uploads/course-spine.svg'),(3,'Спортивный массаж','Восстановление после нагрузок: снятие крепатуры, возвращение тонуса мышцам.',2200.00,60,'🏋️','2026-08-14 20:56:24',7,'/uploads/course-sport.svg'),(4,'Тайский массаж','Традиционный тайский массаж: стрейчинг, давление вдоль сен-линий, 90 минут релакса.',3500.00,90,'🧘','2026-08-14 20:56:24',7,'/uploads/course-thai.svg'),(5,'Детский массаж','Нежный массаж и гимнастика для малышей: снятие колик, укрепление мышц.',1200.00,30,'👶','2026-08-14 20:56:24',7,'/uploads/course-kids.svg'),(6,'Лимфодренажный массаж','Мягкая техника для снятия отёков и улучшения лимфотока.',1800.00,50,'🌊','2026-08-14 20:56:24',7,'/uploads/course-limfo.svg');
