INSERT INTO `site_reviews` VALUES (1,'Анна К.','Выпускница курса «Классический массаж»',5,'Прошла курс с нуля — теперь принимаю клиентов дома. Очень понятная подача и отличные видеоуроки!','2026-08-14 20:56:24'),(2,'Дмитрий П.','Клиент',5,'Записался на сеанс спортивного массажа — спина как новая. Рекомендую!','2026-08-14 20:56:24'),(3,'Марина В.','Выпускница курса «Детский массаж»',5,'Малыш стал спать лучше, колики прошли. Спасибо за курс!','2026-08-14 20:56:24'),(4,'Олег С.','Клиент',4,'Тайский массаж — это что-то невероятное. Мастер — профессионал своего дела.','2026-08-14 20:56:24'),(5,'Екатерина Л.','Выпускница курса «Лечебный массаж»',5,'Практика с триггерными точками реально работает. Благодарю преподавателей!','2026-08-14 20:56:24');
